$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot 'Apply-BrowserEntryIis.ps1'),[ref]$tokens,[ref]$errors)
if($errors.Count){throw 'External health operator parse failed'}
$function=$ast.FindAll({param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -ceq 'Test-BrowserEntryExternalReceipt'},$true)
if($function.Count -ne 1){throw 'Exact receipt validator required'}
. ([scriptblock]::Create($function[0].Extent.Text))
$now=[DateTimeOffset]::UtcNow
$request=[pscustomobject]@{operationId=('bgi_'+('a'*32));correlationId=('bg_'+('b'*32));uri='https://gateway.example/workspace/health';observerSid='S-1-5-21-1-2-3-1001';certificateSha256=('c'*64);applicationHostSha256=('d'*64);issuedAt=$now.AddSeconds(-5).ToString('o')}
$receipt=[pscustomobject]@{version=1;operationId=$request.operationId;correlationId=$request.correlationId;uri=$request.uri;observerSid=$request.observerSid;certificateSha256=$request.certificateSha256;applicationHostSha256=$request.applicationHostSha256;requestSha256=('e'*64);observedAt=$now.ToString('o');tlsValidated=$true;httpStatus=200;bodyStatus='ok'}
[void](Test-BrowserEntryExternalReceipt $receipt $request ('e'*64))
$cases=@(@{version=2},@{operationId=('bgi_'+('f'*32))},@{correlationId=('bg_'+('f'*32))},@{uri='https://other.example/workspace/health'},@{observerSid='S-1-5-18'},@{certificateSha256=('f'*64)},@{applicationHostSha256=('f'*64)},@{requestSha256=('f'*64)},@{tlsValidated=$false},@{tlsValidated='true'},@{httpStatus=401},@{bodyStatus='not-ready'},@{observedAt=$now.AddMinutes(-10).ToString('o')},@{observedAt=$now.AddMinutes(10).ToString('o')},@{arbitrary='extra'})
foreach($patch in $cases){$bad=$receipt|ConvertTo-Json|ConvertFrom-Json;foreach($key in $patch.Keys){$bad|Add-Member -NotePropertyName $key -NotePropertyValue $patch[$key] -Force};$denied=$false;try{[void](Test-BrowserEntryExternalReceipt $bad $request ('e'*64))}catch{$denied=$true};if(-not $denied){throw 'Unsafe external health receipt accepted'}}
foreach($name in @('Hash','Wait-BrowserEntryExternalHealth')){$definition=$ast.FindAll({param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -ceq $name},$true);if($definition.Count -ne 1){throw 'Actual health wait function missing'};. ([scriptblock]::Create($definition[0].Extent.Text))}
$parent=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\');$temporary=Join-Path $parent ('dveh-'+[guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($temporary)
$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;$acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetAccessRuleProtection($true,$false)
foreach($identity in @($sid,'S-1-5-18','S-1-5-32-544')|Select-Object -Unique){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($identity),'FullControl','ContainerInherit,ObjectInherit','None','Allow'))};[IO.Directory]::SetAccessControl($temporary,$acl)
$worker=$null
try{
 $worker=Start-Job -ArgumentList $temporary -ScriptBlock {param($directory) $ErrorActionPreference='Stop';$requestFile=Join-Path $directory 'external-health-request.json';while(-not(Test-Path -LiteralPath $requestFile)){Start-Sleep -Milliseconds 25};$bytes=[IO.File]::ReadAllBytes($requestFile);$r=[Text.Encoding]::UTF8.GetString($bytes)|ConvertFrom-Json;$h=[Security.Cryptography.SHA256]::Create();try{$digest=([BitConverter]::ToString($h.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};$receipt=@{version=1;operationId=$r.operationId;correlationId=$r.correlationId;uri=$r.uri;observerSid=$r.observerSid;certificateSha256=$r.certificateSha256;applicationHostSha256=$r.applicationHostSha256;requestSha256=$digest;observedAt=[DateTimeOffset]::UtcNow.ToString('o');tlsValidated=$true;httpStatus=200;bodyStatus='ok'};$stream=[IO.File]::Open((Join-Path $directory 'external-health-result.json'),[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{$data=[Text.Encoding]::UTF8.GetBytes(($receipt|ConvertTo-Json -Compress));$stream.Write($data,0,$data.Length);$stream.Flush($true);Start-Sleep -Milliseconds 1200}finally{$stream.Dispose()}}
 $approval=[pscustomobject]@{operationId=$request.operationId;correlationId=$request.correlationId;executionSid=$sid;externalHealth=[pscustomobject]@{observerSid=$sid;certificateSha256=$request.certificateSha256}}
 $result=Wait-BrowserEntryExternalHealth $approval ([pscustomobject]@{applicationHostProposedSha256=$request.applicationHostSha256}) $temporary ([Uri]$request.uri)
 if($result.StatusCode -ne 200 -or ($result.Content|ConvertFrom-Json).status -cne 'ok'){throw 'Real sharing-violation wait failed'}
 $worker|Wait-Job -Timeout 10|Out-Null;$worker|Receive-Job -ErrorAction Stop|Out-Null
}finally{if($worker){if($worker.State -cnotin @('Completed','Failed','Stopped')){Stop-Job $worker};Remove-Job $worker};$resolved=[IO.Path]::GetFullPath($temporary);if([IO.Path]::GetDirectoryName($resolved) -cne $parent -or [IO.Path]::GetFileName($resolved) -cnotmatch '^dveh-[a-f0-9]{32}$'){throw 'Owned external health fixture cleanup escaped'};Remove-Item -LiteralPath $resolved -Recurse -Force}
@{status='PASS';checks=(2+$cases.Count);actualOperatorValidator=$true;tlsAndIdentityAndRequestBound=$true;staleAndMalformedDenied=$true;realSharingViolationRetried=$true}|ConvertTo-Json -Compress
